begin;

do $block$
declare
  correction jsonb;
  answer record;
  selected_question_id uuid;
  source_explanation text;
  target_version_id uuid;
  target_version_number integer := 2;
  corrections jsonb := '[{"legacy_id":600465,"prompt":"Un disque a un diamètre de 12 cm. Quelle expression donne son périmètre en centimètres ?","choices":["12π cm","14π cm","24π cm","144π cm"],"correct_position":1,"explanation":"Le périmètre d’un disque vaut π × diamètre, soit 12π cm.","change_comment":"L’unité centimètre est désormais présente dans toutes les propositions."},{"legacy_id":600549,"prompt":"Convertis 3 600 s.","choices":["1 h","60 s","180 min","200 min"],"correct_position":1,"explanation":"3 600 secondes correspondent à 60 minutes, donc à 1 heure.","change_comment":"La proposition « 60 min », également exacte, a été remplacée."},{"legacy_id":600553,"prompt":"Un article coûte 4 €. Si x est le nombre d’articles et y le prix total, quelle relation convient ?","choices":["y = x + 4","y = x − 4","y = 4 × x","y = 4 ÷ x"],"correct_position":3,"explanation":"À prix unitaire constant de 4 €, le prix total est égal à 4 multiplié par le nombre d’articles.","change_comment":"Le coefficient a été rendu concret pour lever toute ambiguïté sur la lettre k."},{"legacy_id":600557,"prompt":"Dans une proportionnalité, tripler une quantité revient à…","choices":["ajouter 3 à la valeur associée","retirer 3 à la valeur associée","multiplier la valeur associée par 3","mettre la valeur associée au carré"],"correct_position":3,"explanation":"Dans une situation proportionnelle, multiplier une quantité par 3 multiplie aussi la valeur associée par 3.","change_comment":"La réponse ne reprend plus directement le verbe « tripler » de l’énoncé."},{"legacy_id":600561,"prompt":"À la boulangerie, chaque baguette coûte 1,20 €. Le prix total est-il proportionnel au nombre de baguettes ?","choices":["Non, car le prix change.","Oui, car on ajoute toujours 1,20 au nombre de baguettes.","Oui, car chaque baguette a le même prix.","On ne peut pas le savoir sans connaître le prix de dix baguettes."],"correct_position":3,"explanation":"Oui, car chaque baguette a le même prix.","change_comment":"Énoncé et distracteurs diversifiés pour évaluer réellement l’identification d’une situation proportionnelle."},{"legacy_id":600562,"prompt":"Une voiture roule à vitesse constante. La distance parcourue est-elle proportionnelle à la durée du trajet ?","choices":["Non, car la durée augmente.","Oui, uniquement si le trajet dure une heure.","Non, car distance et durée n’ont pas la même unité.","Oui, car la même distance est parcourue pendant chaque unité de temps."],"correct_position":4,"explanation":"Oui, car la même distance est parcourue pendant chaque unité de temps.","change_comment":"Énoncé et distracteurs diversifiés pour évaluer réellement l’identification d’une situation proportionnelle."},{"legacy_id":600563,"prompt":"Des pommes sont vendues 3 € le kilogramme, sans réduction. Le prix est-il proportionnel à la masse achetée ?","choices":["Oui, le prix est toujours la masse multipliée par 3.","Non, car une masse ne se mesure pas en euros.","Oui, car le prix augmente toujours de 3 €, quelle que soit la masse ajoutée.","On ne peut le savoir qu’après avoir acheté 3 kg."],"correct_position":1,"explanation":"Oui, le prix est toujours la masse multipliée par 3.","change_comment":"Énoncé et distracteurs diversifiés pour évaluer réellement l’identification d’une situation proportionnelle."},{"legacy_id":600564,"prompt":"Une recette pour 4 personnes utilise 200 g de farine. Si les quantités sont adaptées à l’identique, la farine est-elle proportionnelle au nombre de personnes ?","choices":["Non, car le nombre de personnes est entier.","Oui, car toutes les quantités sont multipliées par le même facteur.","Oui, parce qu’il faut toujours ajouter 200 g.","Non, car la farine se mesure en grammes."],"correct_position":2,"explanation":"Oui, car toutes les quantités sont multipliées par le même facteur.","change_comment":"Énoncé et distracteurs diversifiés pour évaluer réellement l’identification d’une situation proportionnelle."},{"legacy_id":600565,"prompt":"On remplit un réservoir à débit constant, vide au départ. Le volume versé est-il proportionnel à la durée ?","choices":["Non, car le volume augmente.","Oui, même si le débit change.","Oui, car le débit reste constant et le réservoir est vide au départ.","Non, car une durée ne se mesure pas en litres."],"correct_position":3,"explanation":"Oui, car le débit reste constant et le réservoir est vide au départ.","change_comment":"Énoncé et distracteurs diversifiés pour évaluer réellement l’identification d’une situation proportionnelle."},{"legacy_id":600566,"prompt":"Le périmètre d’un carré est-il proportionnel à la longueur de son côté ?","choices":["Non, car un carré a quatre côtés.","Oui, car on ajoute toujours 4 cm.","Non, car le périmètre dépend aussi de l’aire.","Oui, car le périmètre vaut toujours quatre fois la longueur du côté."],"correct_position":4,"explanation":"Oui, car le périmètre vaut toujours quatre fois la longueur du côté.","change_comment":"Énoncé et distracteurs diversifiés pour évaluer réellement l’identification d’une situation proportionnelle."},{"legacy_id":600567,"prompt":"Tous les billets d’entrée coûtent 8 €. Le prix total est-il proportionnel au nombre de billets ?","choices":["Oui, le prix total vaut 8 fois le nombre de billets.","Non, car le nombre de billets est entier.","Oui, car le prix total augmente toujours de 1 €.","On ne peut pas le savoir pour plus de dix billets."],"correct_position":1,"explanation":"Oui, le prix total vaut 8 fois le nombre de billets.","change_comment":"Énoncé et distracteurs diversifiés pour évaluer réellement l’identification d’une situation proportionnelle."},{"legacy_id":600568,"prompt":"Une location coûte 6 € par heure, sans frais de départ. Le coût est-il proportionnel à la durée ?","choices":["Non, car une heure ne vaut pas un euro.","Oui, car il n’y a pas de frais fixe et le tarif horaire est constant.","Oui, même si un forfait de départ est ajouté.","Non, car la durée peut comporter des minutes."],"correct_position":2,"explanation":"Oui, car il n’y a pas de frais fixe et le tarif horaire est constant.","change_comment":"Énoncé et distracteurs diversifiés pour évaluer réellement l’identification d’une situation proportionnelle."},{"legacy_id":600569,"prompt":"Chaque tour de piste mesure 400 m. La distance parcourue est-elle proportionnelle au nombre de tours ?","choices":["Non, car un tour revient au point de départ.","Oui, parce qu’on ajoute 1 au nombre de mètres.","Oui, la distance vaut 400 m multipliés par le nombre de tours.","Non, car 400 est supérieur au nombre de tours."],"correct_position":3,"explanation":"Oui, la distance vaut 400 m multipliés par le nombre de tours.","change_comment":"Énoncé et distracteurs diversifiés pour évaluer réellement l’identification d’une situation proportionnelle."},{"legacy_id":600570,"prompt":"Chaque boîte contient 12 craies. Le nombre total de craies est-il proportionnel au nombre de boîtes ?","choices":["Non, car les boîtes et les craies sont différentes.","Oui, car on ajoute toujours une craie.","On ne peut pas le savoir sans ouvrir toutes les boîtes.","Oui, le total vaut 12 fois le nombre de boîtes."],"correct_position":4,"explanation":"Oui, le total vaut 12 fois le nombre de boîtes.","change_comment":"Énoncé et distracteurs diversifiés pour évaluer réellement l’identification d’une situation proportionnelle."},{"legacy_id":600571,"prompt":"L’âge d’une personne permet-il de calculer sa taille avec un coefficient constant ?","choices":["Non, deux personnes du même âge peuvent avoir des tailles différentes.","Oui, car les deux grandeurs peuvent varier.","Oui, car on peut toujours calculer un rapport.","On peut l’affirmer à partir d’une seule mesure."],"correct_position":1,"explanation":"Non, deux personnes du même âge peuvent avoir des tailles différentes.","change_comment":"La question demande désormais explicitement si un coefficient constant relie les grandeurs."},{"legacy_id":600572,"prompt":"L’aire d’un carré est-elle proportionnelle à la longueur de son côté ?","choices":["Oui, car les deux grandeurs peuvent varier.","Non, l’aire dépend du carré de la longueur du côté.","Oui, car on peut toujours calculer un rapport.","On peut l’affirmer à partir d’une seule mesure."],"correct_position":2,"explanation":"Non, l’aire dépend du carré de la longueur du côté.","change_comment":"La question demande désormais explicitement si un coefficient constant relie les grandeurs."},{"legacy_id":600573,"prompt":"La température extérieure est-elle proportionnelle à l’heure de la journée ?","choices":["Oui, car les deux grandeurs peuvent varier.","Oui, car on peut toujours calculer un rapport.","Non, aucun coefficient constant ne relie l’heure et la température.","On peut l’affirmer à partir d’une seule mesure."],"correct_position":3,"explanation":"Non, aucun coefficient constant ne relie l’heure et la température.","change_comment":"La question demande désormais explicitement si un coefficient constant relie les grandeurs."},{"legacy_id":600574,"prompt":"La pointure d’un enfant est-elle proportionnelle à son âge ?","choices":["Oui, car les deux grandeurs peuvent varier.","Oui, car on peut toujours calculer un rapport.","On peut l’affirmer à partir d’une seule mesure.","Non, la pointure n’augmente pas selon un coefficient constant."],"correct_position":4,"explanation":"Non, la pointure n’augmente pas selon un coefficient constant.","change_comment":"La question demande désormais explicitement si un coefficient constant relie les grandeurs."},{"legacy_id":600575,"prompt":"Une course de taxi comprend 4 € de prise en charge puis 2 € par kilomètre. Le prix est-il proportionnel à la distance ?","choices":["Non, le forfait de départ empêche la proportionnalité.","Oui, car les deux grandeurs peuvent varier.","Oui, car on peut toujours calculer un rapport.","On peut l’affirmer à partir d’une seule mesure."],"correct_position":1,"explanation":"Non, le forfait de départ empêche la proportionnalité.","change_comment":"La question demande désormais explicitement si un coefficient constant relie les grandeurs."},{"legacy_id":600576,"prompt":"L’âge moyen d’un groupe est-il proportionnel au nombre de personnes ?","choices":["Oui, car les deux grandeurs peuvent varier.","Non, il dépend des âges des personnes, pas seulement de leur nombre.","Oui, car on peut toujours calculer un rapport.","On peut l’affirmer à partir d’une seule mesure."],"correct_position":2,"explanation":"Non, il dépend des âges des personnes, pas seulement de leur nombre.","change_comment":"La question demande désormais explicitement si un coefficient constant relie les grandeurs."},{"legacy_id":600577,"prompt":"Pour une distance fixée, la durée est-elle proportionnelle à la vitesse ?","choices":["Oui, car les deux grandeurs peuvent varier.","Oui, car on peut toujours calculer un rapport.","Non, quand la vitesse augmente, la durée diminue.","On peut l’affirmer à partir d’une seule mesure."],"correct_position":3,"explanation":"Non, quand la vitesse augmente, la durée diminue.","change_comment":"La question demande désormais explicitement si un coefficient constant relie les grandeurs."},{"legacy_id":600578,"prompt":"L’aire d’un disque est-elle proportionnelle à son rayon ?","choices":["Oui, car les deux grandeurs peuvent varier.","Oui, car on peut toujours calculer un rapport.","On peut l’affirmer à partir d’une seule mesure.","Non, l’aire dépend du carré du rayon."],"correct_position":4,"explanation":"Non, l’aire dépend du carré du rayon.","change_comment":"La question demande désormais explicitement si un coefficient constant relie les grandeurs."},{"legacy_id":600579,"prompt":"Dans un livre de 200 pages, le nombre de pages restantes est-il proportionnel au nombre de pages lues ?","choices":["Non, pages restantes = 200 − pages lues.","Oui, car les deux grandeurs peuvent varier.","Oui, car on peut toujours calculer un rapport.","On peut l’affirmer à partir d’une seule mesure."],"correct_position":1,"explanation":"Non, pages restantes = 200 − pages lues.","change_comment":"La question demande désormais explicitement si un coefficient constant relie les grandeurs."},{"legacy_id":600580,"prompt":"Sans modèle précis, la température est-elle proportionnelle à l’altitude ?","choices":["Oui, car les deux grandeurs peuvent varier.","Non, on ne dispose pas d’un coefficient constant valable dans toute situation.","Oui, car on peut toujours calculer un rapport.","On peut l’affirmer à partir d’une seule mesure."],"correct_position":2,"explanation":"Non, on ne dispose pas d’un coefficient constant valable dans toute situation.","change_comment":"La question demande désormais explicitement si un coefficient constant relie les grandeurs."},{"legacy_id":600591,"prompt":"Dans un tableau de proportionnalité :\n2 objets → 6 €\n3 objets → 9 €\n\nSans passer par l’unité, déduis le prix de 5 objets.","choices":["15 €","16 €","14 €","20 €"],"correct_position":1,"explanation":"5 = 2 + 3, donc le prix associé vaut 6 + 9 = 15 €.","change_comment":"L’énoncé met explicitement en évidence la linéarité additive."},{"legacy_id":600592,"prompt":"Dans un tableau de proportionnalité :\n4 objets → 12 €\n5 objets → 15 €\n\nSans passer par l’unité, déduis le prix de 9 objets.","choices":["28 €","27 €","26 €","36 €"],"correct_position":2,"explanation":"9 = 4 + 5, donc le prix associé vaut 12 + 15 = 27 €.","change_comment":"L’énoncé met explicitement en évidence la linéarité additive."},{"legacy_id":600593,"prompt":"Dans un tableau de proportionnalité :\n3 objets → 8 €\n6 objets → 16 €\n\nSans passer par l’unité, déduis le prix de 9 objets.","choices":["25 €","23 €","24 €","33 €"],"correct_position":3,"explanation":"9 = 3 + 6, donc le prix associé vaut 8 + 16 = 24 €.","change_comment":"L’énoncé met explicitement en évidence la linéarité additive."},{"legacy_id":600594,"prompt":"Dans un tableau de proportionnalité :\n5 objets → 20 €\n2 objets → 8 €\n\nSans passer par l’unité, déduis le prix de 7 objets.","choices":["29 €","27 €","35 €","28 €"],"correct_position":4,"explanation":"7 = 5 + 2, donc le prix associé vaut 20 + 8 = 28 €.","change_comment":"L’énoncé met explicitement en évidence la linéarité additive."},{"legacy_id":600595,"prompt":"Dans un tableau de proportionnalité :\n7 objets → 14 €\n3 objets → 6 €\n\nSans passer par l’unité, déduis le prix de 10 objets.","choices":["20 €","21 €","19 €","30 €"],"correct_position":1,"explanation":"10 = 7 + 3, donc le prix associé vaut 14 + 6 = 20 €.","change_comment":"L’énoncé met explicitement en évidence la linéarité additive."},{"legacy_id":600596,"prompt":"Dans un tableau de proportionnalité :\n4 objets → 10 €\n8 objets → 20 €\n\nSans passer par l’unité, déduis le prix de 12 objets.","choices":["31 €","30 €","29 €","42 €"],"correct_position":2,"explanation":"12 = 4 + 8, donc le prix associé vaut 10 + 20 = 30 €.","change_comment":"L’énoncé met explicitement en évidence la linéarité additive."},{"legacy_id":600597,"prompt":"Dans un tableau de proportionnalité :\n6 objets → 18 €\n5 objets → 15 €\n\nSans passer par l’unité, déduis le prix de 11 objets.","choices":["34 €","32 €","33 €","44 €"],"correct_position":3,"explanation":"11 = 6 + 5, donc le prix associé vaut 18 + 15 = 33 €.","change_comment":"L’énoncé met explicitement en évidence la linéarité additive."},{"legacy_id":600598,"prompt":"Dans un tableau de proportionnalité :\n9 objets → 27 €\n4 objets → 12 €\n\nSans passer par l’unité, déduis le prix de 13 objets.","choices":["40 €","38 €","52 €","39 €"],"correct_position":4,"explanation":"13 = 9 + 4, donc le prix associé vaut 27 + 12 = 39 €.","change_comment":"L’énoncé met explicitement en évidence la linéarité additive."},{"legacy_id":600599,"prompt":"Dans un tableau de proportionnalité :\n12 objets → 30 €\n8 objets → 20 €\n\nSans passer par l’unité, déduis le prix de 20 objets.","choices":["50 €","51 €","49 €","70 €"],"correct_position":1,"explanation":"20 = 12 + 8, donc le prix associé vaut 30 + 20 = 50 €.","change_comment":"L’énoncé met explicitement en évidence la linéarité additive."},{"legacy_id":600600,"prompt":"Dans un tableau de proportionnalité :\n15 objets → 45 €\n7 objets → 21 €\n\nSans passer par l’unité, déduis le prix de 22 objets.","choices":["67 €","66 €","65 €","88 €"],"correct_position":2,"explanation":"22 = 15 + 7, donc le prix associé vaut 45 + 21 = 66 €.","change_comment":"L’énoncé met explicitement en évidence la linéarité additive."},{"legacy_id":600611,"prompt":"Lis ce tableau de proportionnalité :\n\nQuantité | 2 | 5\nPrix (€) | 6 | 15\n\nQuel prix correspond à la quantité 5 ?","choices":["15 €","6 €","5 €","17 €"],"correct_position":1,"explanation":"Dans la colonne de la quantité 5, on lit directement le prix associé.","change_comment":"Un tableau lisible est désormais affiché dans l’énoncé."},{"legacy_id":600612,"prompt":"Lis ce tableau de proportionnalité :\n\nQuantité | 3 | 7\nPrix (€) | 12 | 28\n\nQuel prix correspond à la quantité 7 ?","choices":["12 €","28 €","7 €","31 €"],"correct_position":2,"explanation":"Dans la colonne de la quantité 7, on lit directement le prix associé.","change_comment":"Un tableau lisible est désormais affiché dans l’énoncé."},{"legacy_id":600613,"prompt":"Lis ce tableau de proportionnalité :\n\nQuantité | 4 | 8\nPrix (€) | 10 | 20\n\nQuel prix correspond à la quantité 8 ?","choices":["10 €","8 €","20 €","24 €"],"correct_position":3,"explanation":"Dans la colonne de la quantité 8, on lit directement le prix associé.","change_comment":"Un tableau lisible est désormais affiché dans l’énoncé."},{"legacy_id":600614,"prompt":"Lis ce tableau de proportionnalité :\n\nQuantité | 5 | 9\nPrix (€) | 20 | 36\n\nQuel prix correspond à la quantité 9 ?","choices":["20 €","9 €","41 €","36 €"],"correct_position":4,"explanation":"Dans la colonne de la quantité 9, on lit directement le prix associé.","change_comment":"Un tableau lisible est désormais affiché dans l’énoncé."},{"legacy_id":600615,"prompt":"Lis ce tableau de proportionnalité :\n\nQuantité | 6 | 11\nPrix (€) | 18 | 33\n\nQuel prix correspond à la quantité 11 ?","choices":["33 €","18 €","11 €","39 €"],"correct_position":1,"explanation":"Dans la colonne de la quantité 11, on lit directement le prix associé.","change_comment":"Un tableau lisible est désormais affiché dans l’énoncé."},{"legacy_id":600616,"prompt":"Lis ce tableau de proportionnalité :\n\nQuantité | 7 | 15\nPrix (€) | 14 | 30\n\nQuel prix correspond à la quantité 15 ?","choices":["14 €","30 €","15 €","37 €"],"correct_position":2,"explanation":"Dans la colonne de la quantité 15, on lit directement le prix associé.","change_comment":"Un tableau lisible est désormais affiché dans l’énoncé."},{"legacy_id":600617,"prompt":"Lis ce tableau de proportionnalité :\n\nQuantité | 8 | 12\nPrix (€) | 24 | 36\n\nQuel prix correspond à la quantité 12 ?","choices":["24 €","12 €","36 €","44 €"],"correct_position":3,"explanation":"Dans la colonne de la quantité 12, on lit directement le prix associé.","change_comment":"Un tableau lisible est désormais affiché dans l’énoncé."},{"legacy_id":600618,"prompt":"Lis ce tableau de proportionnalité :\n\nQuantité | 9 | 13\nPrix (€) | 45 | 65\n\nQuel prix correspond à la quantité 13 ?","choices":["45 €","13 €","74 €","65 €"],"correct_position":4,"explanation":"Dans la colonne de la quantité 13, on lit directement le prix associé.","change_comment":"Un tableau lisible est désormais affiché dans l’énoncé."},{"legacy_id":600619,"prompt":"Lis ce tableau de proportionnalité :\n\nQuantité | 10 | 18\nPrix (€) | 25 | 45\n\nQuel prix correspond à la quantité 18 ?","choices":["45 €","25 €","18 €","55 €"],"correct_position":1,"explanation":"Dans la colonne de la quantité 18, on lit directement le prix associé.","change_comment":"Un tableau lisible est désormais affiché dans l’énoncé."},{"legacy_id":600620,"prompt":"Lis ce tableau de proportionnalité :\n\nQuantité | 12 | 20\nPrix (€) | 36 | 60\n\nQuel prix correspond à la quantité 20 ?","choices":["36 €","60 €","20 €","72 €"],"correct_